func load(path string) (cfg *Config, err error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, err
	}
	defer func() {
		// wrap whatever we are returning
		if err != nil {
			err = fmt.Errorf("load %s: %w", path, err)
		}
	}()

	return parse(f)
}

func f() error {              // unnamed
	var err error
	defer func() {
		err = errors.New("changed")   // assigns a LOCAL
	}()
	return err                    // the value was already copied out
}
// returns nil

func safe() (err error) {
	defer func() {
		if r := recover(); r != nil {
			err = fmt.Errorf("recovered: %v", r)
		}
	}()

	return risky()
}

func main() {
	defer func() {
		recover()      // does NOT protect the goroutine below
	}()

	go func() {
		panic("boom")  // takes the whole process down
	}()

	select {}
}
